def get_user_dashboard(user_id):
    user = db.query('SELECT * FROM users WHERE id = ?', user_id)
    orders = db.query('SELECT * FROM orders WHERE user_id = ?', user_id)
    products = []
    for order in orders:
        items = db.query('SELECT * FROM order_items WHERE order_id = ?', order['id'])
        for item in items:
            product = db.query('SELECT * FROM products WHERE id = ?', item['product_id'])
            products.append(product)
    recommendations = []
    all_products = db.query('SELECT * FROM products')
    for p in all_products:
        if p['category'] in [prod['category'] for prod in products]:
            recommendations.append(p)
    return {'user': user, 'orders': orders, 'recommendations': recommendations[:5]}
